// Idiomas do Anvil3D: o texto em português é a própria chave; o dicionário dá o inglês.
// tr('texto') traduz um texto fixo; tt`texto ${x}` traduz um texto com valores (vira "texto {0}").
// Para acrescentar um texto novo: escreva em português com tr/tt e ponha a versão em inglês em EN.
let idioma = 'pt';
export const IDIOMAS = { pt: 'Português', en: 'English' };
export const idiomaAtual = () => idioma;
export function definirIdioma(l) { idioma = l === 'en' ? 'en' : 'pt'; }

export function tr(s, ...args) {
  let r = idioma === 'en' ? (EN[s] ?? s) : s;
  if (args.length) r = r.replace(/\{(\d+)\}/g, (_, i) => args[i]);
  return r;
}
export function tt(partes, ...vals) {
  let k = partes[0];
  for (let i = 0; i < vals.length; i++) k += `{${i}}` + partes[i + 1];
  return tr(k, ...vals);
}
// número com a vírgula ou o ponto do idioma
export const decimal = (v, casas = 2) => { const s = Number(v).toFixed(casas); return idioma === 'en' ? s : s.replace('.', ','); };
export const inteiro = n => Math.round(n).toLocaleString(idioma === 'en' ? 'en-US' : 'pt-BR');

